const el = document.querySelector('#text')
const statusEl = document.querySelector('#status')

const DEBOUNCE_MS = 400
const PULSE_MS = 1200

let debounceTimer = null
let pulseTimer = null
let pending = false
let editVersion = 0

function setStatus(message, state) {
  statusEl.textContent = message
  statusEl.classList.remove('saving', 'saved', 'error')
  if (state) statusEl.classList.add(state)
}

function stamp() {
  const now = new Date()
  const hours = String(now.getHours()).padStart(2, '0')
  const minutes = String(now.getMinutes()).padStart(2, '0')
  return `${hours}:${minutes}`
}

function pulse() {
  for (const node of [statusEl, el]) node.classList.add('saved')
  clearTimeout(pulseTimer)
  pulseTimer = setTimeout(() => {
    for (const node of [statusEl, el]) node.classList.remove('saved')
  }, PULSE_MS)
}

async function save({ keepalive = false } = {}) {
  clearTimeout(debounceTimer)
  debounceTimer = null
  if (!pending) return
  const savingVersion = editVersion
  const text = el.textContent

  try {
    const res = await fetch('/api/text', {
      method: 'PUT',
      body: JSON.stringify({ text }),
      keepalive,
    })
    if (!res.ok) throw new Error(`PUT /api/text responded ${res.status}`)
    if (editVersion === savingVersion) {
      pending = false
      setStatus(`Saved ${stamp()}`, 'saved')
      pulse()
    }
  } catch (error) {
    console.error('Could not save the greeting:', error)
    if (editVersion === savingVersion && pending) {
      setStatus('Not saved — will retry', 'error')
    }
  }
}

function scheduleSave() {
  pending = true
  editVersion += 1
  setStatus('Saving…', 'saving')
  clearTimeout(debounceTimer)
  debounceTimer = setTimeout(save, DEBOUNCE_MS)
}

el.addEventListener('input', scheduleSave)
el.addEventListener('keydown', (event) => {
  // The greeting is a single line; Enter would inject <div>/<br> nodes.
  if (event.key === 'Enter') event.preventDefault()
})
el.addEventListener('blur', () => {
  if (pending) save({ keepalive: true })
})
window.addEventListener('pagehide', () => {
  if (pending) save({ keepalive: true })
})

const loadingVersion = editVersion
try {
  const res = await fetch('/api/text')
  if (!res.ok) throw new Error(`GET /api/text responded ${res.status}`)
  const { text } = await res.json()
  if (editVersion === loadingVersion) {
    el.textContent = text
    setStatus('Type to edit')
  }
} catch (error) {
  console.error('Could not load the greeting:', error)
  if (editVersion === loadingVersion) {
    setStatus('Not loaded — showing default', 'error')
  }
}

import { createServer as createHttpServer } from 'node:http'
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

export const MAX_TEXT_BYTES = 10000

const publicDir = join(dirname(fileURLToPath(import.meta.url)), 'public')

// Explicit asset map rather than a path-resolving static handler: no traversal
// surface, and adding a file is one deliberate line here.
const ASSETS = {
  '/': { file: join(publicDir, 'index.html'), type: 'text/html; charset=utf-8' },
  '/styles.css': { file: join(publicDir, 'styles.css'), type: 'text/css; charset=utf-8' },
  '/app.js': { file: join(publicDir, 'app.js'), type: 'text/javascript; charset=utf-8' },
}

function send(res, status, payload, headers = {}) {
  const body = JSON.stringify(payload)
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(body),
    ...headers,
  })
  res.end(body)
}

// Resolves to the body text, or null once the body exceeds MAX_TEXT_BYTES.
function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = []
    let received = 0
    let tooLarge = false
    req.on('data', (chunk) => {
      if (tooLarge) return
      received += chunk.length
      if (received > MAX_TEXT_BYTES) {
        tooLarge = true
        chunks.length = 0
        return
      }
      chunks.push(chunk)
    })
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')))
    req.on('error', reject)
  })
}

export function createServer(store) {
  const assets = new Map(
    Object.entries(ASSETS).map(([route, asset]) => [route, { type: asset.type, body: readFileSync(asset.file) }]),
  )

  async function handleTextPut(req, res) {
    const body = await readBody(req)
    if (body === null) return send(res, 413, { error: 'text too long' })

    let parsed
    try {
      parsed = JSON.parse(body)
    } catch {
      return send(res, 400, { error: 'text must be a string' })
    }
    if (typeof parsed?.text !== 'string') return send(res, 400, { error: 'text must be a string' })

    store.write(parsed.text)
    send(res, 200, { text: parsed.text })
  }

  return createHttpServer(async (req, res) => {
    try {
      const pathname = new URL(req.url, 'http://localhost').pathname
      if (req.method !== 'GET' && req.method !== 'PUT') {
        return send(res, 405, { error: 'method not allowed' }, { allow: 'GET, PUT' })
      }

      if (pathname === '/api/text') {
        if (req.method === 'GET') return send(res, 200, { text: store.read() })
        return await handleTextPut(req, res)
      }

      const asset = assets.get(pathname)
      if (!asset) return send(res, 404, { error: 'not found' })
      if (req.method !== 'GET') return send(res, 405, { error: 'method not allowed' }, { allow: 'GET' })

      res.writeHead(200, {
        'content-type': asset.type,
        'content-length': asset.body.length,
      })
      res.end(asset.body)
    } catch (error) {
      console.error(`${req.method} ${req.url} failed:`, error)
      if (!res.headersSent) send(res, 500, { error: 'internal' })
      else res.destroy(error)
    }
  })
}

import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { createFileStore } from './store.js'
import { createServer } from './server.js'

const root = dirname(fileURLToPath(import.meta.url))
const portValue = process.env.PORT ?? '3000'
const port = Number(portValue)
if (!/^\d+$/.test(portValue) || !Number.isInteger(port) || port < 1 || port > 65535) {
  throw new RangeError('PORT must be an integer from 1 to 65535')
}
const dataFile = process.env.DATA_FILE ? resolve(process.env.DATA_FILE) : join(root, 'data', 'hello.json')

createServer(createFileStore(dataFile)).listen(port, () => {
  console.log(`Editing at http://localhost:${port}  (data: ${dataFile})`)
})

