  "name": "hello-world",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node main.js",
    "test": "node --test tests/",
    "check": "node --check store.js && node --check server.js && node --check main.js && node --check public/app.js"
  }
}

